-- ============================================================
-- CƠ SỞ DỮ LIỆU: webbanpc
-- Chuyển đổi từ SQL Server (webpc.sql) sang MySQL / MariaDB (XAMPP)
-- Bảng mã: utf8mb4 (Unicode Tiếng Việt hoàn chỉnh)
-- ============================================================

CREATE DATABASE IF NOT EXISTS `webbanpc` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `webbanpc`;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';

-- ------------------------------------------------------------
-- XÓA BẢNG CŨ NẾU ĐÃ TỒN TẠI
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `ChiTietDonHang`;
DROP TABLE IF EXISTS `ChiTietGioHang`;
DROP TABLE IF EXISTS `DonHang`;
DROP TABLE IF EXISTS `GioHang`;
DROP TABLE IF EXISTS `SanPham`;
DROP TABLE IF EXISTS `DanhMuc`;
DROP TABLE IF EXISTS `HangSanXuat`;
DROP TABLE IF EXISTS `NguoiDung`;

-- ------------------------------------------------------------
-- 1. Bảng `NguoiDung` (Khách hàng & Quản trị viên)
-- ------------------------------------------------------------
CREATE TABLE `NguoiDung` (
  `UserName` VARCHAR(50) NOT NULL,
  `HoTen` VARCHAR(50) NOT NULL,
  `Email` VARCHAR(100) NOT NULL,
  `MatKhau` VARCHAR(255) NOT NULL,
  `SoDienThoai` VARCHAR(20) NOT NULL,
  `DiaChi` VARCHAR(255) NOT NULL,
  `Quyen` INT NOT NULL DEFAULT 1 COMMENT '0: Admin, 1: Khách hàng, 2: Nhân viên/Khác',
  PRIMARY KEY (`UserName`),
  UNIQUE KEY `UQ_NguoiDung_Email` (`Email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 2. Bảng `HangSanXuat` (Hãng sản xuất / Thương hiệu)
-- ------------------------------------------------------------
CREATE TABLE `HangSanXuat` (
  `BrandID` INT NOT NULL AUTO_INCREMENT,
  `TenHang` VARCHAR(50) NOT NULL,
  PRIMARY KEY (`BrandID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 3. Bảng `DanhMuc` (Danh mục sản phẩm)
-- ------------------------------------------------------------
CREATE TABLE `DanhMuc` (
  `CategoryID` INT NOT NULL AUTO_INCREMENT,
  `TenDanhMuc` VARCHAR(50) NOT NULL,
  `AnhDM` VARCHAR(500) NOT NULL,
  PRIMARY KEY (`CategoryID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 4. Bảng `SanPham` (Sản phẩm máy tính & linh kiện)
-- ------------------------------------------------------------
CREATE TABLE `SanPham` (
  `ProductID` INT NOT NULL AUTO_INCREMENT,
  `TenSanPham` VARCHAR(500) NOT NULL,
  `Gia` BIGINT NOT NULL COMMENT 'Đơn giá VNĐ',
  `HinhAnh` VARCHAR(500) NOT NULL,
  `MoTa` LONGTEXT NOT NULL,
  `ThongSoKyThuat` LONGTEXT NOT NULL,
  `SoLuongTon` INT NOT NULL DEFAULT 0,
  `BrandID` INT DEFAULT NULL,
  `CategoryID` INT NOT NULL,
  PRIMARY KEY (`ProductID`),
  KEY `FK_SanPham_Brand` (`BrandID`),
  KEY `FK_SanPham_Category` (`CategoryID`),
  CONSTRAINT `CK_SanPham_Gia` CHECK (`Gia` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 5. Bảng `GioHang` (Giỏ hàng người dùng)
-- ------------------------------------------------------------
CREATE TABLE `GioHang` (
  `CartID` INT NOT NULL AUTO_INCREMENT,
  `UserName` VARCHAR(50) NOT NULL,
  PRIMARY KEY (`CartID`),
  KEY `FK_GioHang_UserName` (`UserName`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 6. Bảng `ChiTietGioHang` (Mặt hàng trong giỏ)
-- ------------------------------------------------------------
CREATE TABLE `ChiTietGioHang` (
  `CartItemID` INT NOT NULL AUTO_INCREMENT,
  `CartID` INT NOT NULL,
  `ProductID` INT NOT NULL,
  `SoLuong` INT NOT NULL DEFAULT 1,
  PRIMARY KEY (`CartItemID`),
  KEY `FK_ChiTietGioHang_CartID` (`CartID`),
  KEY `FK_ChiTietGioHang_ProductID` (`ProductID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 7. Bảng `DonHang` (Hóa đơn / Đơn đặt hàng)
-- ------------------------------------------------------------
CREATE TABLE `DonHang` (
  `OrderID` INT NOT NULL AUTO_INCREMENT,
  `UserName` VARCHAR(50) NOT NULL,
  `NgayDat` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `TongTien` BIGINT NOT NULL,
  `TrangThai` INT DEFAULT 0 COMMENT '0: Chờ xử lý, 1: Đã xác nhận, 2: Đang giao, 3: Đã giao/hoàn tất',
  `DiaChiGiaoHang` VARCHAR(255) NOT NULL,
  `PhuongThucThanhToan` VARCHAR(50) DEFAULT 'COD',
  PRIMARY KEY (`OrderID`),
  KEY `FK_DonHang_UserName` (`UserName`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 8. Bảng `ChiTietDonHang` (Chi tiết mặt hàng trong đơn)
-- ------------------------------------------------------------
CREATE TABLE `ChiTietDonHang` (
  `OrderDetailID` INT NOT NULL AUTO_INCREMENT,
  `OrderID` INT NOT NULL,
  `ProductID` INT NOT NULL,
  `SoLuong` INT NOT NULL,
  `GiaTaiThoiDiemMua` BIGINT NOT NULL,
  PRIMARY KEY (`OrderDetailID`),
  KEY `FK_ChiTietDonHang_OrderID` (`OrderID`),
  KEY `FK_ChiTietDonHang_ProductID` (`ProductID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

