INSERT INTO `SanPham` (`ProductID`, `TenSanPham`, `Gia`, `HinhAnh`, `MoTa`, `ThongSoKyThuat`, `SoLuongTon`, `BrandID`, `CategoryID`) VALUES (1, 'Bàn Phím Razer Huntsman V3 Pro Mini 60% Analog Optical Esports Keyboard White Edition - US Layout', 4590000, 'Banphim/RAZER/1/250-9306-ban-phim-razer-v3-pro-mini-5.jpg', '
<h4 class="mb-3">Đánh Giá Chi Tiết Bàn Phím Razer Huntsman V3 Pro Mini </h4>
                        <b style="color:black">Thiết kế layout Razer Huntsman V3 Pro Mini 60% nhỏ gọn</b><br />
                        <p>-Bàn phím cơ<b style="color:lightcoral">Razer Huntsman V3 Pro Mini</b> Lý tưởng cho các thiết lập tối giản hoặc nhỏ hơn, tạo ra không gian bàn cao cấp. Kiểu dáng nhỏ gọn của nó cũng giúp cho việc di chuyển tốt và dễ dàng hơn, bạn có thể thỏa thích mang đến mọi nơi để sử dụng.</p><br />

                        <b style="color:black">Keycap PBT double-shot</b><br/>
                        <p>Cứng hơn và bền hơn nhựa ABS, các phím bấm có kết cấu, chắc chắn trên bàn phím này sẽ không bị mài mòn với lớp hoàn thiện sáng bóng và chữ sẽ không bao giờ mờ nhờ quá trình đúc đôi.</p><br>

                        <b style="color:black">Razer Analog Optical Switches Gen-2</b><br />
                        <p>Tối đa hóa độ chính xác và phản hồi cho bàn phím cơ <b style="color:lightcoral">Razer Huntsman V3 Pro Min</b> bao gồm <b style="color:lightcoral">Rapid Trigger </b>cho đầu vào lặp lại cực nhanh, phạm vi tác động có thể điều chỉnh từ 0,1 đến 4,0 mm và tuổi thọ 100 triệu lần nhấn phím.</p><br>

                        <b style="color:black">Phím chức năng được tích hợp</b><br />
                        <p>Các phím bổ trợ phía dưới, bên phải, bên trên nhỏ này tăng gấp đôi dưới dạng phím mũi tên khi gõ, cung cấp khả năng điều hướng thuận tiện mà bạn thường chỉ có thể có được từ các kiểu dáng lớn hơn</p><br>

                       

                        <b style="color:black">Tông Kết</b><br />
                        <p><b style="color:lightcoral">Bàn Phím Razer Huntsman V3 Pro Mini 60% Analog Optical Esports Keyboard White Edition - US Layout</b>  xứng đáng là bộ PC được săn đón nhiều nhất trong thời gian tới đây. </p><br>

', '
<p class="mb-4">
                <b>Chuẩn kết nối:</b> Dây USB <br />
                 - Thiết kế 60% nhỏ gọn <br />
                 - Keycap PBT Doubleshot bền bỉ<br />
                 - Phím bấm RAZER™ ANALOG OPTICAL SWITCHES GEN-2<br />
                 - Tính năng Onboard Memory và tuỳ chỉnh các hiệu ứng led có sẵn trên phím<br />
                 - Thiết kế khung nhôm chắc chắn<br />
                 - Led RGB Chroma 16.8 triệu màu<br />
 </p>
', 5, 6, 3);
INSERT INTO `SanPham` (`ProductID`, `TenSanPham`, `Gia`, `HinhAnh`, `MoTa`, `ThongSoKyThuat`, `SoLuongTon`, `BrandID`, `CategoryID`) VALUES (2, 'Bàn phím Cơ Razer BlackWidow V3
	Quartz Edition - Green Switch
	RZ03-03541800-R3M1', 2290000, 'Banphim/RAZER/2/250-8837-c---razer-blackwidow-v3---quartz-edition---green-switch---rz03-03541800-r3m1-1.jpg', '
<h4 class="mb-3">Đánh giá chi tiết bàn phím Razer BlackWidow V3 Quartz Edition Green Switch </h4>
                        <b style="color:black">Razer BlackWidow V3 hỗ trợ Switch cho ánh sáng Razer Chroma RGB sáng hơn</b><br />
                        <p>-Bàn phím cơ<b style="color:lightcoral"> Razer BlackWidow V3 Quartz Edition Green Switch </b>hiết kế switch hoàn toàn trong suốt của nó thể hiện sự rực rỡ thực sự của những gì Razer Chroma RGB, người dùng có thể tùy chỉnh ánh sáng theo sở thích mang đến những trải nghiệm tốt nhất khi chơi game khi có thể đồng nhất âm thanh với ánh sáng bàn phím khi chơi game, xem phim.</p><br />

                        <b style="color:black">Các phím media điều khiển thuận tiện</b><br />
                        <p>Để mang đến cho người dùng nhiều tiện ích khi sử dụng, thay vì sử dụng phím tắt kết hợp như những dòng bàn phím cơ giá rẻ khác. <b style="color:lightcoral">Razer BlackWidow V3 Quartz Edition Green Switch</b> được trang bị hệ thống media với chức năng điều khiển âm thanh bằng con lăn một cách vô cùng tiện lợi.</p><br>

                        <b style="color:black">Keycap với công nghệ Doubleshot ABS</b><br />
                        <p>Người dùng có thể sử dụng bàn phím <b style="color:lightcoral">Razer BlackWidow V3 Quartz Edition Green Switch</b> một cách thoải mái mà không cần phải lo đến tình trạng mòn hoặc mất chữ trên bàn phím. Vì <b style="color:lightcoral">Razer </b> đã sử dụng công nghệ khắc Doubleshot ABS, cho độ dày gấp đôi giúp tăng độ bền, các keycaps trên bàn phím cơ chơi game này cũng có thành cực dày khiến chúng cực kỳ cứng chắc để chịu được việc sử dụng nhiều lần trong thời gian dài.</p><br>

                        <b style="color:black">Phụ kiện đi kèm chất lượng cao cấp</b><br />
                        <p>Nhằm nâng cao chất lượng và cải thiện chất lượng với người tiêu dùng, Razer đã trang bị phần kê tay mềm có nam châm bám vào bàn phím và được căn chỉnh hoàn hảo để giảm áp lực lên cổ tay của bạn khi bạn sử dụng <b style="color:lightcoral">Razer BlackWidow V3 Quartz Edition Green Switch</b> Vì vậy, đây là một trong những mẫu bàn phím <b style="color:lightcoral">Razer </b> mang đến cho bạn cảm giác thoải mái hơn rất nhiều khi chơi game trong thời gian dài.</p><br>
                        


                        <b style="color:black">Tông Kết</b><br />
                        <p
', '
<p class="mb-4">
                    Phiên bản giới hạn màu hồng cá tính <br />
                    Sử dụng switch cơ học độc quyền của Razer với phần housing được làm trong suốt giúp cho đèn led hiển thị đẹp hơn<br />
                    Keycap ABS Doubleshot<br />
                    Đi kèm kê tay chống mỏi có thể tháo rời<br />
                    Thiết kế khung nhôm chắc chắn<br />
                    Led RGB Chroma 16.8 triệu màu<br />
                    Núm xoay Multimedia tiện lợi<br />
                </p>

', 5, 6, 3);
INSERT INTO `SanPham` (`ProductID`, `TenSanPham`, `Gia`, `HinhAnh`, `MoTa`, `ThongSoKyThuat`, `SoLuongTon`, `BrandID`, `CategoryID`) VALUES (3, 'Bàn Phím Cơ Razer DeathStalker V2 Pro
White Edition - Clicky Purple Switch
RZ03-04363500-R3M1', 4290000, 'Banphim/RAZER/3/10489-ban-phim-co-razer-deathstalker-v2-pro-white-edition-clicky-purple-switch-rz03-04363500-r3m1--1-.jpg', '
<h4 class="mb-3">Đánh giá chi tiết Bàn Phím Cơ Razer DeathStalker V2 Pro - RZ03-04363500-R3M1 </h4>
                        <b style="color:black">RAZER™ Low-profile Optical Switches (Purple Switch)</b><br />
                        <p>Loại switch đặc biệt này mang lại âm thanh Clicky sắc và rõ, với lực nhấn 50g và tuổi thọ lên đến 70 triệu lần bấm. Độ phản hồi nhanh gần như không có độ trễ, cho trải nghiệm tốt nhất thị trường.</p><br />

                        <b style="color:black">Pin bàn phím lên đến 40 giờ</b><br />
                        <p><b style="color:lightcoral">Razer DeathStalker V2 Pro</b> sở hữu hiệu suất năng lượng ấn tượng, sử dụng ít năng lượng hơn để vận hành. Bàn phím có thể hoạt động liên tục trong 40 giờ, giúp bạn yên tâm sử dụng mà không lo hết pin đột ngột</p><br>

                        <b style="color:black">Keycaps cứng cáp và siêu bền</b><br />
                        <p>Keycaps được thiết kế cứng hơn cả loại ABS doubleshot, với các cạnh sắc nét và sang trọng. Khi kết hợp với hệ thống RGB, các keycaps trở nên rõ ràng và đẹp mắt, tạo nên phần nhìn nghệ thuật nhất.</p><br>

                        <b style="color:black">Kết nối không dây nhanh hơn, tiện lợi hơn</b><br />
                        <p><b style="color:lightcoral">Razer DeathStalker V2 Pro</b> có hai cách kết nối: công nghệ Receiver 2.4GHz riêng biệt của <b style="color:lightcoral">Razer</b>, nhanh hơn 25% so với công nghệ không dây khác, và Bluetooth 5.0, mang lại cảm giác không độ trễ.  </p><br>



                        <b style="color:black">Tông Kết</b><br />
                        <p><b style="color:lightcoral">Bàn Phím Cơ Razer DeathStalker V2 Pro - RZ03-04363500-R3M1</b> xứng đáng là bộ PC được săn đón nhiều nhất trong thời gian tới đây. </p><br>

', '
<p class="mb-4">
                    <b>Loại sản phẩm: </b>Bàn phím cơ không dây<br />
                    <b>Kết nối: </b>USB 2.4GHz, Bluetooth 5.0 và cáp USB-C tháo rời <br />
                    <b>Keyswitch: </b>Razer Low-Profile Clicky Optical<br />
                    <b>Độ bền Switch: </b>70 triệu lượt nhấn<br />
                    <b>Dạng bàn phím: </b>Fullsize<br />
                    Tính năng Onboard Memory và tuỳ chỉnh các hiệu ứng led có sẵn trên phím<br />
                    Thiết kế khung nhôm chắc chắn<br />
                    Led RGB Chroma 16.8 triệu màu<br />

                </p>

', 5, 6, 3);
INSERT INTO `SanPham` (`ProductID`, `TenSanPham`, `Gia`, `HinhAnh`, `MoTa`, `ThongSoKyThuat`, `SoLuongTon`, `BrandID`, `CategoryID`) VALUES (4, 'Chuột Logitech G703 HERO Lightspeed Wireless', 1869000, 'Chuot/LOGITECH/4/250-7178-g703.jpg', '
<h4 class="mb-3">Đánh Giá Chi Tiết Chuột Razer Deathadder Essential </h4>
                        <b style="color:black">Chuột Razer Deathadder Essential sở hữu thiết kế công thái học</b><br />
                        <p><b style="color:lightcoral">Razer Deathadder Essential</b> được <b style="color:lightcoral">Razer</b> hiết kế với kiểu dáng công thái học (Ergonomic) cổ điển. Thiết kế đẹp mắt và khác biệt ở các dòng chuột máy tính khác, tạo ra sự thoải mái, cho phép người chơi duy trì mức hiệu suất cao trong suốt thời gian chơi game dài.</p><br />

                        <b style="color:black">Trang bị công nghệ hiện đại</b><br />
                        <p>Trang bị đến 5 nút Hyperesponse người chơi có thể lập trình được, một trong những dòng chuột gaming giá rẻ mang đến cho người chơi có được lợi thế cạnh tranh khi điều khiển trận đấu. Nút cơ học công nghệ Razer Mechanical với độ tin cậy cao cùng với độ bền cao lên đến 10 triệu lần nhấp.</p><br>

                        <b style="color:black">Nâng cao khả năng kiểm soát trận đấu</b><br />
                        <p>Khả năng kiểm soát trận đấu chính là ưu điểm của những dòng sản phẩm bàn phím cơ, tai nghe gaming trong cùng hệ sinh thái của <b style="color:lightcoral">Razer</b>. Và <b style="color:lightcoral">Razer Deathadder Essential</b> cũng không ngoại lệ, sở hữu cảm biến quang học lên đến 6.400 DPI cho phép vuốt chuột đi nhanh và chuẩn xác, cung cấp khả năng kiểm soát tốt hơn cho game thủ với những nhu cầu thiết yếu nhất. Mang đến lợi thế cho người dùng khi trải nghiệm các tựa game yêu thích.</p><br>


                        <b style="color:black">Tông Kết</b><br />
                        <p>Trên đây là những tính năng nổi trội của chuột Razer DeathAdder Essential. Để khám phá thêm nhiều sản phẩm Gaming Gears, hãy đến ngay Showroom để trải nghiệm.</p><br>

', '
<p class="mb-4">
                    <b>DPI:</b>16000<br />
                    <b>Gia tốc tối đa:</b> >40G<br />
                    <b>Tốc độ tối đa:</b> >400IPS<br />
                    - Chuột chơi game thế hệ mới nhất của Logitech<br />
                    - Thiết kế công thái học cho người dùng tay phải<br />
                    - Led 16,8 triệu màu điều chỉnh bằng phần mềm<br />
                    - Hai chế độ không dây và có dây<br />
                    
                    
                </p>

', 5, 7, 5);
INSERT INTO `SanPham` (`ProductID`, `TenSanPham`, `Gia`, `HinhAnh`, `MoTa`, `ThongSoKyThuat`, `SoLuongTon`, `BrandID`, `CategoryID`) VALUES (5, 'PC Gaming - Sniper I4060 - BL', 19090000, 'img2/PC_gaming/pc_gaming_5/pc_gaming_5_25122025023106188.jpg', '<h4 class="mb-3">Đánh giá chi tiết PC Gaming - Sniper I4060 - WH</h4>
                        <b style="color:black">PC Gaming Sniper I4060 WH mạnh mẽ CPU Intel Core i5 12400F</b><br>
                        <p>-Với 6 lõi và 12 luồng mạnh mẽ,<b style="color:lightcoral">CPU Intel Core i5 - 12400F</b>  được cung cấp sức mạnh từ nền tảng LGA 1700 và kiến ​​trúc Alder Lake hiện đại, giúp mang lại hiệu năng vượt trội so với người anh em thế hệ trước. Ngoài ra, CPU tương thích với nhiều bo mạch chủ phổ biến như H610, B660, H670 và Z690 để đảm bảo trải nghiệm tuyệt vời. </p><br>

                        <b style="color:black">Bo Mạch Chủ Asus B760M-AYW WIFI D4</b><br>
                        <p><b style="color:lightcoral">Mainboard Asus B760M-AYW WIFI D4</b> được thiết kế truyền tải điện năng mạnh mẽ, giải pháp tản nhiệt toàn diện và các tùy chọn điều chỉnh thông minh. Cung cấp cho người dùng và PC một loạt các tối ưu hóa hiệu năng thông qua công nghệ hiện đại.</p><br>

                        <b style="color:black">RAM Adata XPG D50 DDR4 RGB 8GB</b><br>
                        <p>Ngoài ra <b style="color:lightcoral">RAM Adata XPG D50 DDR4 RGB 8GB</b> một trong những linh kiện quan trọng không kém phần nổi bật trong bộ PC Gaming Sniper I4060 WH là RAM Adata XPG D50. Đạt tốc độ lên tới 4800MHz và hỗ trợ dung lượng tối đa 32GB, XPG D50 giúp cho PC sở hữu kho lưu trữ hoàn hảo. Kiểu dáng sản phẩm mang lại cái nhìn đầy hấp dẫn với những đường nét hình học tạo phong cách sang trọng.</p><br>

                        <b style="color:black">Ổ cứng SSD Hiksemi Future Eco 512G</b><br>
                        <p>Mang đến làn sóng công nghệ mới cho PC của bạn với SSD Hiksemi Future Eco 512G PCIe Gen 4x4 NVMe còn đem tới tốc độ đọc ghi là khoảng 5000MB/s, nhanh hơn hẳn các dòng ổ cứng SSD PCIe Gen 3 thông thường.</p><br>

                        <b style="color:black">Card Màn Hình ASUS DUAL RTX 060 O8G</b><br>
                        <p>Nâng cấp PC của bạn với card màn hình<b style="color:lightcoral"> ASUS DUAL RTX 4060 O8G</b>  sở hữu các giải pháp làm mát tiên tiến từ các card đồ họa hàng đầu  bao gồm hai quạt công nghệ hướng trục để tối đa hóa luồng không khí đến bộ tản nhiệt. Các cải tiến này giúp ASUS Dual trở thành sự lựa chọn hoàn hảo cho các game thủ mong muốn có hiệu năng đồ họa mạnh mẽ trong một thiết kế nhỏ gọn.</p><br>

                        <b style="color:black">Nguồn Antec CSK550 550W 80 Plus Bronze</b><br>
                        <p>Nguồn <b style="color:lightcoral"> Antec CSK550 </b>  là sản phẩm thế hệ mới của Antec được chế tạo để đảm bảo chất lượng, hiệu quả và hiệu suất. Với chứng nhận 80 PLUS BRONZE, quạt yên tĩnh và bao gồm các biện pháp bảo vệ cấp công nghiệp đảm bảo rằng nguồn điện được cung cấp cho hệ thống của bạn là an toàn và đáng tin cậy trong mọi môi trường.</p><br>

                        <b style="color:black">Vỏ Case Xigmatek PANO M Arctic</b><br>
                        <p>Xigmatek <b style="color:lightcoral"> PANO M Arctic </b>  là một sản phẩm chất lượng cao, được thiết kế đặc biệt, với kiểu dáng hiện đại, không chỉ mang lại trải nghiệm giải trí tuyệt vời mà còn làm tăng thêm vẻ đẹp cho bàn làm việc của bạn. Vỏ case được xây dựng mang lại không gian rộng rãi cho PC và sự linh hoạt cho việc lắp đặt các linh kiện gaming hàng đầu.</p><br>

                        <b style="color:black">Tông Kết</b><br>
                        <p><b style="color:lightcoral"> PC Gaming Sniper I4060 WH </b>  xứng đáng là bộ PC được săn đón nhiều nhất trong thời gian tới đây. </p><br>

', '<p class="mb-4">
                    <b>CPU:</b> Intel Core i5-12400F 6C/12T (Up To 4.40GHz, 18MB, Socket 1700, Alder Lake) Hàng Tray <br>
                    <b>Bo Mạch Chủ:</b> Asus B760M-AYW WIFI D4 <br>
                    <b>RAM:</b> Adata XPG D50 DDR4 RGB 8GB 3200Mhz - White x2<br>
                    <b>Ổ cứng SSD:</b> Hiksemi Future Eco 512G PCIe Gen 4x4 NVMe<br>
                    <b>Card Màn Hình:</b> ASUS DUAL RTX4060 O8G WHITE<br>
                    <b>Nguồn:</b> Antec B650 EC - 80 Plus Bronze<br>
                    <b>Vỏ Case:</b> Xigmatek PANO M Arctic<br>

                </p>

', 5, NULL, 2);
INSERT INTO `SanPham` (`ProductID`, `TenSanPham`, `Gia`, `HinhAnh`, `MoTa`, `ThongSoKyThuat`, `SoLuongTon`, `BrandID`, `CategoryID`) VALUES (7, 'Chuột Corsair Nightsabre RGB Wireless', 3890000, 'Chuot/CORSAIR/1/250-9506-tnc-store-chuot-corsair-26.jpg', '
<h4 class="mb-3">Đánh Giá Chi Tiết Chuột Corsair Nightsabre RGB Wireeless</h4>
                        <b style="color:black">Chuột Nightsabre được lập trình các nút bấm hiện đại </b><br />
                        <p><b style="color:lightcoral">Nightsabre</b> dễ dàng lập trình 11 nút trong iCUE và lưu vào tối đa năm bộ lưu trữ.</p><br />

                        <b style="color:black">Tận hưởng sự linh hoạt</b><br />
                        <p>Kết nối qua slipstream không dây ở tốc độ dưới 1 mili giây và 2000hz hyper-polling, bluetooth hoặc usb có dây để chơi khi đang sạc.</p><br>

                        <b style="color:black">Vượt qua đối thủ</b><br />
                        <p>Chơi tới 100 giờ trong một lần sạc và chỉ cần 15 phút sạc sẽ giúp bạn chơi game thêm 20 giờ nữa.</p><br>

                        <b style="color:black">Chính xác đến từng chi tiết nhỏ</b><br />
                        <p>Cảm biến quang chuột Corsair Marksman 26000 DPI cực kỳ chính xác ghi lại mọi chuyển động, có thể tùy chỉnh theo từng bước DPI.</p><br>


                        <b style="color:black">Phản ứng ngay lập tức</b><br />
                        <p>Nút Nightsabre đăng ký ngay lập tức các đầu vào của bạn, vì vậy bạn luôn tấn công. Công tắc quang học bền bỉ loại bỏ độ trễ debounce, giúp bạn nhấp nhanh chóng với tốc độ đáng kinh ngạc.</p><br>

                        <b style="color:black">Tông Kết</b><br />
                        <p>Trên đây là những tính năng nổi trội của chuột Corsair Nightsabre. Để khám phá thêm nhiều sản phẩm Gaming Gears, hãy đến ngay Showroom để trải nghiệm.</p><br>

', '
<p class="mb-4">
                    <b>DPI:</b>16000<br />
                    <b>Trọng lượng:</b> 96G<br />
                    <b>Độ bền Switch chuột: </b>50 triệu lượt nhấn<br />
                    - Chuột chơi game thế hệ mới nhất của Logitech<br />
                    - Thiết kế công thái học cho người dùng tay phải<br />
                    - Led 16,8 triệu màu điều chỉnh bằng phần mềm<br />
                    - Hai chế độ không dây và có dây<br />
                    

                </p>

', 5, 3, 5);
INSERT INTO `SanPham` (`ProductID`, `TenSanPham`, `Gia`, `HinhAnh`, `MoTa`, `ThongSoKyThuat`, `SoLuongTon`, `BrandID`, `CategoryID`) VALUES (8, 'Chuột Razer DeathAdder Essential - Ergonomic Wired_RZ01-03850100-R3M1', 449000, 'Chuot/RAZER/1/250-7591-chuot-razer-deathadder-essential-ergonomic-001.jpg', '
<h4 class="mb-3">Đánh Giá Chi Tiết Bàn Phím Razer Huntsman V3 Pro Mini </h4>
                        <b style="color:black">Thiết kế layout Razer Huntsman V3 Pro Mini 60% nhỏ gọn</b><br />
                        <p>-Bàn phím cơ<b style="color:lightcoral">Razer Huntsman V3 Pro Mini</b> Lý tưởng cho các thiết lập tối giản hoặc nhỏ hơn, tạo ra không gian bàn cao cấp. Kiểu dáng nhỏ gọn của nó cũng giúp cho việc di chuyển tốt và dễ dàng hơn, bạn có thể thỏa thích mang đến mọi nơi để sử dụng.</p><br />

                        <b style="color:black">Keycap PBT double-shot</b><br />
                        <p>Cứng hơn và bền hơn nhựa ABS, các phím bấm có kết cấu, chắc chắn trên bàn phím này sẽ không bị mài mòn với lớp hoàn thiện sáng bóng và chữ sẽ không bao giờ mờ nhờ quá trình đúc đôi.</p><br>

                        <b style="color:black">Razer Analog Optical Switches Gen-2</b><br />
                        <p>Tối đa hóa độ chính xác và phản hồi cho bàn phím cơ <b style="color:lightcoral">Razer Huntsman V3 Pro Min</b> bao gồm <b style="color:lightcoral">Rapid Trigger </b>cho đầu vào lặp lại cực nhanh, phạm vi tác động có thể điều chỉnh từ 0,1 đến 4,0 mm và tuổi thọ 100 triệu lần nhấn phím.</p><br>

                        <b style="color:black">Phím chức năng được tích hợp</b><br />
                        <p>Các phím bổ trợ phía dưới, bên phải, bên trên nhỏ này tăng gấp đôi dưới dạng phím mũi tên khi gõ, cung cấp khả năng điều hướng thuận tiện mà bạn thường chỉ có thể có được từ các kiểu dáng lớn hơn</p><br>



                        <b style="color:black">Tông Kết</b><br />
                        <p><b style="color:lightcoral">Bàn Phím Razer Huntsman V3 Pro Mini 60% Analog Optical Esports Keyboard White Edition - US Layout</b>  xứng đáng là bộ PC được săn đón nhiều nhất trong thời gian tới đây. </p><br>

', '
<p class="mb-4">
                    <b>DPI:</b>16000<br />
                    <b>Gia tốc tối đa:</b> 30G<br />
                    <b>Tần số quét:</b>1000 Hz<br />
                    5 nút bấm, tuổi thọ 10 triệu lần nhấp<br />
                </p>

', 5, 6, 5);
INSERT INTO `SanPham` (`ProductID`, `TenSanPham`, `Gia`, `HinhAnh`, `MoTa`, `ThongSoKyThuat`, `SoLuongTon`, `BrandID`, `CategoryID`) VALUES (9, 'Màn hình Acer Nitro VG270 IPS/ Full HD/ 75Hz', 3290000, 'Manhinh/ACER/1/8299-vg270-s-2.jpg', '
<h4 class="mb-3">Đánh giá chi tiết MÀN HÌNH ACER ED320Q X 31.5 inch / FHD / VA / 240Hz</h4>
                        <b style="color:black">Thiết kế viền cực mỏng</b><br />
                        <p><b style="color:lightcoral">ACER ED320Q X 31.5 inch / FHD / VA / 240Hz</b> có kích thước  31.5inch và sở hữu tỷ lệ 16:9 rất chuẩn để chơi game.Đồng thời, chân đế còn được trang bị tính năng công thái học, giúp màn hình có thể xoay nghiêng lên trên trong khoảng từ 5-20 độ, đảm bảo cho anh em không bị mỏi cỏ trong những trận combat kéo dài.</p><br />

                        <b style="color:black">Độ phân giải Full HD</b><br />
                        <p>Chất lượng hình ảnh mới là thứ khiến màn hình <b style="color:lightcoral">ACER ED320Q X 31.5 inch / FHD / VA / 240Hz</b> được đánh giá cao nhất. Độ phân giải Full HD với độ phủ màu 99% sRGB và hỗ trợ hiển thị 16,7 triệu màu mang đến độ hiển thị màu sắc nét và vô cùng rực rỡ.</p><br>

                        <b style="color:black">Trang bị tấm nền VA</b><br />
                        <p>TBên cạnh đó, <b style="color:lightcoral">ACER ED320Q X 31.5 inch / FHD / VA / 240Hz</b> được trang bị tấm nền IPS cho chất lượng hình ảnh vượt bậc so với các tấm nền TN hay VA, đảm bảo góc nhìn rộng hơn 178 độ ở cả 4 góc trên dưới trái phải, cho anh em những trải nghiệm thị giác trọn vẹn nhất.</p><br>

                        <b style="color:black">Cấu hình chuẩn Esport</b><br />
                        <p>Cấu hình chuẩn Esport của màn hình <b style="color:lightcoral">ACER ED320Q X 31.5 inch / FHD / VA / 240Hz</b> còn được thể hiện ở tần số quét 75Hz và tốc độ phản hồi chỉ 1ms, đảm bảo cho những tác vụ chơi game cơ bản của anh em được vận hành một cách trơn tru.</p><br>

                        <b style="color:black">Tổng Kết</b><br />
                        <p><b style="color:lightcoral">ACER ED320Q X 31.5 inch / FHD / VA / 240Hz</b> là một món hàng “đo ni đóng giày” thật sự dành cho anh em game thủ phổ thông. Một chiếc màn hình chính hãng được thiết kế riêng cho những anh em game thủ ở phân khúc tầm trung.</p><br>

', '
<p class="mb-4">
                    <b>Kích thước:</b> 31.5 inch Cong<br />
                    <b>Tấm nền:</b> VA<br /> 
                    <b>Độ phân giải:</b> Full HD (1920x1080)<br />
                    <b>Tốc độ làm mới :</b> 240Hz<br />
                    <b>Thời gian đáp ứng:</b> 1ms (VRB)<br />
                </p>

', 5, 9, 4);
INSERT INTO `SanPham` (`ProductID`, `TenSanPham`, `Gia`, `HinhAnh`, `MoTa`, `ThongSoKyThuat`, `SoLuongTon`, `BrandID`, `CategoryID`) VALUES (11, 'Màn Hình ACER X34 GS 34 inch/IPS/4K/144Hz/SPK', 23990000, 'Manhinh/ACER/2/250-8894-acer-x34-gs-1.jpg', '
<h4 class="mb-3">Đánh giá chi tiết màn Hình ACER X34 GS 34 inch/IPS/4K/144Hz/HDMI/DP/USB/LED/SPK</h4>
                        <b style="color:black">Thiết kế viền cực mỏng</b><br />
                        <p><b style="color:lightcoral">ACER X34 GS 34 inch/IPS/4K/144Hz/HDMI/DP/USB/LED/SPK</b> Lcó kích thước 27 inch và sở hữu tỷ lệ 16:9 rất chuẩn để chơi game.Đồng thời, chân đế còn được trang bị tính năng công thái học, giúp màn hình có thể xoay nghiêng lên trên trong khoảng từ 5-20 độ, đảm bảo cho anh em không bị mỏi cỏ trong những trận combat kéo dài.</p><br />

                        <b style="color:black">Độ phân giải Full HD</b><br />
                        <p>Chất lượng hình ảnh mới là thứ khiến màn hình <b style="color:lightcoral">ACER X34 GS 34 inch/IPS/4K/144Hz/HDMI/DP/USB/LED/SPK</b> được đánh giá cao nhất. Độ phân giải Full HD với độ phủ màu 99% sRGB và hỗ trợ hiển thị 16,7 triệu màu mang đến độ hiển thị màu sắc nét và vô cùng rực rỡ.</p><br>

                        <b style="color:black">Trang bị tấm nền IPS</b><br />
                        <p>TBên cạnh đó, <b style="color:lightcoral">ACER X34 GS 34 inch/IPS/4K/144Hz/HDMI/DP/USB/LED/SPK</b> được trang bị tấm nền IPS cho chất lượng hình ảnh vượt bậc so với các tấm nền TN hay VA, đảm bảo góc nhìn rộng hơn 178 độ ở cả 4 góc trên dưới trái phải, cho anh em những trải nghiệm thị giác trọn vẹn nhất.</p><br>

                        <b style="color:black">Cấu hình chuẩn Esport</b><br />
                        <p>Cấu hình chuẩn Esport của màn hình <b style="color:lightcoral">ACER X34 GS 34 inch/IPS/4K/144Hz/HDMI/DP/USB/LED/SPK</b> còn được thể hiện ở tần số quét 75Hz và tốc độ phản hồi chỉ 1ms, đảm bảo cho những tác vụ chơi game cơ bản của anh em được vận hành một cách trơn tru.</p><br>

                        <b style="color:black">Công nghệ AMD Freesync</b><br />
                        <p>Công nghệ <b style="color:lightcoral">AMD Freesync</b> giúp chống tình trạng xé hình và loại bỏ hiện tượng bóng mờ, giúp hình ảnh xuất ra mượt mà nhất. Trong khi đó, công nghệ <b style="color:lightcoral">BlueLightShield</b> và <b style="color:lightcoral">ComfyView</b>ại giúp hạn chế ánh sáng xanh và đem lại trải nghiệm tốt hơn trong điều kiện quá sáng hoặc quá tối.</p><br>

                        <b style="color:black">Tổng Kết</b><br />
                        <p><b style="color:lightcoral">ACER X34 GS 34 inch/IPS/4K/144Hz/HDMI/DP/USB/LED/SPK</b> là một món hàng “đo ni đóng giày” thật sự dành cho anh em game thủ phổ thông. Một chiếc màn hình chính hãng được thiết kế riêng cho những anh em game thủ ở phân khúc tầm trung.</p><br>

', '
<p class="mb-4">
                    <b>Loại màn hình:</b> Cong 1900R<br />
                    <b>Kích thước:</b> 34 inch<br />
                    <b>Tấm nền:</b>IPS<br />
                    <b>Chuẩn màu:</b>98% DCI-P3 (125% sRGB)<br />
                    <b>Độ phân giải:</b>WQHD (3440x1440)<br />
                    <b>Thời gian đáp ứng:</b> 1ms (VRB)<br />

                </p>

', 5, 9, 4);
INSERT INTO `SanPham` (`ProductID`, `TenSanPham`, `Gia`, `HinhAnh`, `MoTa`, `ThongSoKyThuat`, `SoLuongTon`, `BrandID`, `CategoryID`) VALUES (12, 'MÀN HÌNH ACER ED320Q X 31.5 inch / FHD / VA / 240Hz', 6290000, 'Manhinh/ACER/3/250-8707-ed320q-x-1.jpg', '
<h4 class="mb-3">Đánh giá chi tiết MÀN HÌNH ACER ED320Q X 31.5 inch / FHD / VA / 240Hz</h4>
                        <b style="color:black">Thiết kế viền cực mỏng</b><br />
                        <p><b style="color:lightcoral">ACER ED320Q X 31.5 inch / FHD / VA / 240Hz</b> có kích thước  31.5inch và sở hữu tỷ lệ 16:9 rất chuẩn để chơi game.Đồng thời, chân đế còn được trang bị tính năng công thái học, giúp màn hình có thể xoay nghiêng lên trên trong khoảng từ 5-20 độ, đảm bảo cho anh em không bị mỏi cỏ trong những trận combat kéo dài.</p><br />

                        <b style="color:black">Độ phân giải Full HD</b><br />
                        <p>Chất lượng hình ảnh mới là thứ khiến màn hình <b style="color:lightcoral">ACER ED320Q X 31.5 inch / FHD / VA / 240Hz</b> được đánh giá cao nhất. Độ phân giải Full HD với độ phủ màu 99% sRGB và hỗ trợ hiển thị 16,7 triệu màu mang đến độ hiển thị màu sắc nét và vô cùng rực rỡ.</p><br>

                        <b style="color:black">Trang bị tấm nền VA</b><br />
                        <p>TBên cạnh đó, <b style="color:lightcoral">ACER ED320Q X 31.5 inch / FHD / VA / 240Hz</b> được trang bị tấm nền IPS cho chất lượng hình ảnh vượt bậc so với các tấm nền TN hay VA, đảm bảo góc nhìn rộng hơn 178 độ ở cả 4 góc trên dưới trái phải, cho anh em những trải nghiệm thị giác trọn vẹn nhất.</p><br>

                        <b style="color:black">Cấu hình chuẩn Esport</b><br />
                        <p>Cấu hình chuẩn Esport của màn hình <b style="color:lightcoral">ACER ED320Q X 31.5 inch / FHD / VA / 240Hz</b> còn được thể hiện ở tần số quét 75Hz và tốc độ phản hồi chỉ 1ms, đảm bảo cho những tác vụ chơi game cơ bản của anh em được vận hành một cách trơn tru.</p><br>

                        <b style="color:black">Tổng Kết</b><br />
                        <p><b style="color:lightcoral">ACER ED320Q X 31.5 inch / FHD / VA / 240Hz</b> là một món hàng “đo ni đóng giày” thật sự dành cho anh em game thủ phổ thông. Một chiếc màn hình chính hãng được thiết kế riêng cho những anh em game thủ ở phân khúc tầm trung.</p><br>

', '
<p class="mb-4">
                    <b>Kích thước:</b> 31.5 inch Cong<br />
                    <b>Tấm nền:</b> VA<br /> 
                    <b>Độ phân giải:</b> Full HD (1920x1080)<br />
                    <b>Tốc độ làm mới :</b> 240Hz<br />
                    <b>Thời gian đáp ứng:</b> 1ms (VRB)<br />
                </p>

', 5, 9, 4);
INSERT INTO `SanPham` (`ProductID`, `TenSanPham`, `Gia`, `HinhAnh`, `MoTa`, `ThongSoKyThuat`, `SoLuongTon`, `BrandID`, `CategoryID`) VALUES (14, 'PC Gaming - Sniper I4060 - WH', 19090000, 'img2/PC_gaming/pc_gaming_14/pc_gaming_14_22122025.jpg', '<h4 class="mb-3">Đánh giá chi tiết PC Gaming - Sniper I4060 - WH</h4>
                        <b style="color:black">PC Gaming Sniper I4060 WH mạnh mẽ CPU Intel Core i5 12400F</b><br>
                        <p>-Với 6 lõi và 12 luồng mạnh mẽ,<b style="color:lightcoral">CPU Intel Core i5 - 12400F</b>  được cung cấp sức mạnh từ nền tảng LGA 1700 và kiến ​​trúc Alder Lake hiện đại, giúp mang lại hiệu năng vượt trội so với người anh em thế hệ trước. Ngoài ra, CPU tương thích với nhiều bo mạch chủ phổ biến như H610, B660, H670 và Z690 để đảm bảo trải nghiệm tuyệt vời. </p><br>

                        <b style="color:black">Bo Mạch Chủ Asus B760M-AYW WIFI D4</b><br>
                        <p><b style="color:lightcoral">Mainboard Asus B760M-AYW WIFI D4</b> được thiết kế truyền tải điện năng mạnh mẽ, giải pháp tản nhiệt toàn diện và các tùy chọn điều chỉnh thông minh. Cung cấp cho người dùng và PC một loạt các tối ưu hóa hiệu năng thông qua công nghệ hiện đại.</p><br>

                        <b style="color:black">RAM Adata XPG D50 DDR4 RGB 8GB</b><br>
                        <p>Ngoài ra <b style="color:lightcoral">RAM Adata XPG D50 DDR4 RGB 8GB</b> một trong những linh kiện quan trọng không kém phần nổi bật trong bộ PC Gaming Sniper I4060 WH là RAM Adata XPG D50. Đạt tốc độ lên tới 4800MHz và hỗ trợ dung lượng tối đa 32GB, XPG D50 giúp cho PC sở hữu kho lưu trữ hoàn hảo. Kiểu dáng sản phẩm mang lại cái nhìn đầy hấp dẫn với những đường nét hình học tạo phong cách sang trọng.</p><br>

                        <b style="color:black">Ổ cứng SSD Hiksemi Future Eco 512G</b><br>
                        <p>Mang đến làn sóng công nghệ mới cho PC của bạn với SSD Hiksemi Future Eco 512G PCIe Gen 4x4 NVMe còn đem tới tốc độ đọc ghi là khoảng 5000MB/s, nhanh hơn hẳn các dòng ổ cứng SSD PCIe Gen 3 thông thường.</p><br>

                        <b style="color:black">Card Màn Hình ASUS DUAL RTX 060 O8G</b><br>
                        <p>Nâng cấp PC của bạn với card màn hình<b style="color:lightcoral"> ASUS DUAL RTX 4060 O8G</b>  sở hữu các giải pháp làm mát tiên tiến từ các card đồ họa hàng đầu  bao gồm hai quạt công nghệ hướng trục để tối đa hóa luồng không khí đến bộ tản nhiệt. Các cải tiến này giúp ASUS Dual trở thành sự lựa chọn hoàn hảo cho các game thủ mong muốn có hiệu năng đồ họa mạnh mẽ trong một thiết kế nhỏ gọn.</p><br>

                        <b style="color:black">Nguồn Antec CSK550 550W 80 Plus Bronze</b><br>
                        <p>Nguồn <b style="color:lightcoral"> Antec CSK550 </b>  là sản phẩm thế hệ mới của Antec được chế tạo để đảm bảo chất lượng, hiệu quả và hiệu suất. Với chứng nhận 80 PLUS BRONZE, quạt yên tĩnh và bao gồm các biện pháp bảo vệ cấp công nghiệp đảm bảo rằng nguồn điện được cung cấp cho hệ thống của bạn là an toàn và đáng tin cậy trong mọi môi trường.</p><br>

                        <b style="color:black">Vỏ Case Xigmatek PANO M Arctic</b><br>
                        <p>Xigmatek <b style="color:lightcoral"> PANO M Arctic </b>  là một sản phẩm chất lượng cao, được thiết kế đặc biệt, với kiểu dáng hiện đại, không chỉ mang lại trải nghiệm giải trí tuyệt vời mà còn làm tăng thêm vẻ đẹp cho bàn làm việc của bạn. Vỏ case được xây dựng mang lại không gian rộng rãi cho PC và sự linh hoạt cho việc lắp đặt các linh kiện gaming hàng đầu.</p><br>

                        <b style="color:black">Tông Kết</b><br>
                        <p> PC Gaming Sniper I4060 WH <b style="color:lightcoral"> PC Gaming Sniper I4060 WH </b>  xứng đáng là bộ PC được săn đón nhiều nhất trong thời gian tới đây. </p><br>

', '<p class="mb-4">
                    <b>CPU:</b> Intel Core i5-12400F 6C/12T (Up To 4.40GHz, 18MB, Socket 1700, Alder Lake) Hàng Tray <br>
                    <b>Bo Mạch Chủ:</b> Asus B760M-AYW WIFI D4 <br>
                    <b>RAM:</b> Adata XPG D50 DDR4 RGB 8GB 3200Mhz - White x2<br>
                    <b>Ổ cứng SSD:</b> Hiksemi Future Eco 512G PCIe Gen 4x4 NVMe<br>
                    <b>Card Màn Hình:</b> ASUS DUAL RTX4060 O8G WHITE<br>
                    <b>Nguồn:</b> Antec B650 EC - 80 Plus Bronze<br>
                    <b>Vỏ Case:</b> Xigmatek PANO M Arctic<br>

                </p>

', 5, NULL, 2);
INSERT INTO `SanPham` (`ProductID`, `TenSanPham`, `Gia`, `HinhAnh`, `MoTa`, `ThongSoKyThuat`, `SoLuongTon`, `BrandID`, `CategoryID`) VALUES (15, 'PC Gaming - Sentinel I4090 Eva 02 Limited Edition 01', 129990000, 'img2/PC_gaming/PC3/250-9204-sentinal-i4090-eva-02-limited-edition-01.jpg', '
<h4 class="mb-3">Đánh giá chi tiết PC Gaming - Sentinal I4090 Eva 02 Limited Edition 01</h4>
                        <b style="color:black">Intel Core I9 14900K 24C/32T</b><br />
                        <p>-Với 6 lõi và 12 luồng mạnh mẽ,<b style="color:lightcoral">CPU Intel Core I9 14900K</b>  thế hệ 14 này được cải tiến nhiều về tốc độ, hiệu suất cùng với sự kết hợp giữa nhân tiết kiệm điện Efficient-cores (E-cores). Cùng với đó là nhân hiệu năng cao Performance cores (P-cores) </p><br />
                        <b style="color:black">Bo Mạch Chủ Asus ROG MAXIMUS Z790 HERO EVA 02 DDR5</b><br />
                        <p><b style="color:lightcoral">ROG Maximus Z790 Hero EVA-02 Edition</b> là kết quả của sự hợp tác mới xoay quanh EVA-02 và Asuka của bộ anime Evangelion nổi tiếng từ lâu. Sau khi thu hút sự chú ý của bạn với chủ đề màu đỏ cam đặc trưng của EVA-02 và các vệt màu xanh lá cây, sự khởi sắc về mặt nghệ thuật tiếp tục xuất hiện: thiết kế AT Field bao quanh ổ cắm CPU và đèn Polymo trên nắp I/O chuyển đổi giữa Asuka và EVA thông thường -02. Thiết kế tấm ốp lưng thể hiện chế độ EVA-02 “The Beast” và các mẫu Evangelion, làm tăng thêm vẻ hấp dẫn về mặt hình ảnh của bo mạch chủ. Và với tư cách là bo mạch chủ ROG Maximus, nó cung cấp tất cả các tính năng mạnh mẽ, làm mát và linh hoạt cần thiết để nâng hiệu năng lên một tầm cao mới.</p><br>

                        <b style="color:black">Nguồn Asus ROG Thor 1000W - 80 Plus Platinum II Eva Edition</b><br />
                        <p>Sau sự kết hợp thành công với Gundam thì nay ASUS tiếp tục chiều fan anime/manga với một collab với series anime không kém phần nổi tiếng đến từ đất nước mặt trời mọc, Evangelion. Những hình tượng về Angel, Unit trong bộ phim đã tạo cảm hứng xây dựng nên những chi tiết bắt mắt trên <b style="color:lightcoral">nguồn máy tính ASUS ROG Thor 1000W Platinum II EVA Edition</b> Những chi tiết từ logo ASUS ROG đến hình vẽ liên quan đến Evangelion được trau chuốt bắt mắt, khi đó logo nổi bật với đèn nền. Mặt trên là những đường chéo bắt ngang qua trên phần quạt tản nhiệt tạo cảm giác về một bộ máy chuẩn bị tham gia vào trận chiến. Đây sẽ sự lựa chọn tuyệt vời tô điểm cho case máy tính.</p><br />
                        
                        <b style="color:black">Card Màn Hình Asus ROG Strix RTX® 4090 OC EVA 02 Edition 24GB</b><br />
                        <p>ROG tiếp tục dự án EVANGELION dành cho game thủ với thiết kế máy hoàn toàn mới xoay quanh EVA-02 và Asuka. Bước vào tương lai với Asus ROG Strix GeForce RTX 4090 OC EVA 02 Edition. Được thiết kế với sự hợp tác của dự án EVANGELION, card đồ họa mạnh mẽ này tự hào có tính thẩm mỹ tuyệt đẹp lấy cảm hứng từ EVA-02. Tấm che và tấm ốp lưng có các yếu tố thiết kế phức tạp, trong khi bảng ARGB phía trước thể hiện hiệu ứng đồng bộ hóa mang tính biểu tượng. </p><br>

                        <b style="color:black">Tản nhiệt nước ASUS ROG RYUJIN III 360 ARGB EVA-02 EDITION</b><br />
                        <p><b style="color:lightcoral"> Tản nhiệt nước ASUS ROG RYUJIN III 360 ARGB EVA-02 EDITION </b> tùy chỉnh có thể ghép với nhau thông qua một đầu nối nam châm, kết nối các quạt và truyền tín hiệu điều khiển và nguồn điện. Chỉ cần một dây cáp cho cả hai quạt, giúp việc cài đặt và quản lý dây cáp trở nên đơn giản hơn bao giờ hết.</p><br>

                        <b style="color:black">RAM Corsair Dominator Platinum RGB 32GB (2x16GB) 5600Mhz</b><br />
                        <p><b style="color:lightcoral">Corsair DOMINATOR PLATINUM RGB</b> Heatspreader sử dụng chuẩn DDR5 mới nhất cho hiệu năng tốt hơn hẳn DDR4, sẵn sàng cho các thế hệ CPU & bo mạch chủ mới nhất đến từ Intel. </p><br>

                        <b style="color:black">Ổ cứng SSD Samsung 990 PRO 2TB M.2 NVMe PCIe Gen 4.0 x4</b><br />
                        <p><b style="color:lightcoral"> Ổ cứng SSD Samsung 990 PRO 2TB M.2 NVMe PCIe Gen 4.0 x4 </b> là sản phẩm cực kỳ mới sử dụng công nghệ cao. Giao diện PCIe Gen 4.0 mang đến sự vượt trội hơn Gen 3 rất nhiều. Tốc độ của nó có thể lên tới 7450MB/s, đọc – ghi ngẫu nhiên đạt tới 1550K IOPS. Đây là một hiệu suất cực kỳ cao cho máy tính hoạt động với những tác vụ đòi hỏi yêu cầu cao. </p><br>

                        <b style="color:black">Vỏ case Asus ROG Hyperion GR701 EVA</b><br />
                        <p><b style="color:lightcoral"> Case máy tính Asus ROG Hyperion GR701 EVA </b> hỗ trợ tản nhiệt kép 420mm. Bốn quạt 140mm và trung tâm quạt tích hợp mang đến nhiều khả năng tối ưu về lưu lượng không khí.</p><br>

                        <b style="color:black">Tông Kết</b><br />
                        <p>
                            Với sự mạnh mẽ về hiệu năng cũng như sự tinh tế về thiết kế của từng linh kiện, PC Gaming Sentinal I4090 Eva 02 Limited Edition 01 xứng đáng là bộ PC Gaming quốc dân được săn đón nhiều nhất trong thời gian tới đây.



                            Hi vọng qua bài viết này, TNC Store giúp anh em có thể lựa chọn cho mình bộ PC ưng ý nhất ! Ngoài ra, TNC Store còn xây dựng cấu hình PC phù hợp với nhu cầu sử dụng của khách hàng.
                        </p><br>
', '
<p class="mb-4">
                    <b>CPU:</b> Intel Core I9 14900K 24C/32T ( Up to 6.0GHz, 36MB ) _ hàng NK <br />
                    <b>Bo Mạch Chủ:</b> Asus ROG MAXIMUS Z790 HERO EVA 02 DDR5 <br />
                    <b>RAM:</b> Corsair Dominator Platinum RGB 32GB (2x16GB) 5600Mhz *2<br />
                    <b>Ổ cứng SSD:</b> SSD Samsung 990 PRO 2TB M.2 NVMe PCIe Gen 4.0 x4<br />
                    <b>Card Màn Hình:</b> Asus ROG Strix RTX® 4090 OC EVA 02 Edition 24GB<br />
                    <b>Nguồn:</b> Asus ROG Thor 1000W - 80 Plus Platinum II Eva Edition<br />
                    <b>Vỏ Case:</b> Asus ROG Hyperion GR701 EVA<br />
                    <b>Tản nhiệt nước</b> ASUS ROG RYUJIN III 360 ARGB EVA-02 EDITION ( Tặng theo PC)<br />

                </p>
', 5, NULL, 2);
INSERT INTO `SanPham` (`ProductID`, `TenSanPham`, `Gia`, `HinhAnh`, `MoTa`, `ThongSoKyThuat`, `SoLuongTon`, `BrandID`, `CategoryID`) VALUES (16, 'PC Gaming - Sentinel I4090 - BL', 116799000, 'img2/PC_gaming/PC4/250-7799-pc-gaming-sentinel-i4090-bl--10-.jpg', '
<h4 class="mb-3">Đánh giá chi tiết PC Gaming - Sentinal I4090 Eva 02 Limited Edition 01</h4>
                        <b style="color:black">Intel Core I9 14900K 24C/32T</b><br />
                        <p>-Với 6 lõi và 12 luồng mạnh mẽ,<b style="color:lightcoral">CPU Intel Core I9 14900K</b>  thế hệ 14 này được cải tiến nhiều về tốc độ, hiệu suất cùng với sự kết hợp giữa nhân tiết kiệm điện Efficient-cores (E-cores). Cùng với đó là nhân hiệu năng cao Performance cores (P-cores) </p><br />

                        <b style="color:black">Mainboard ASUS ROG STRIX Z790-F GAMING WIFI II</b><br />
                        <p><b style="color:lightcoral">Bo Mạch Chủ ASUS ROG STRIX Z790-F GAMING WIFI II </b> hiện đại cùng khả năng tương thích cao nhất. Thu hút ánh nhìn đầu tiên của người dùng với thiết kế mạnh mẽ, logo Asus đặc trưng và bắt mắt.Với thiết kế DIY thân thiện với người dùng, hỗ trợ DDR5, năm khe cắm M.2 và khe cắm SSD PCIe 5.0 NVMe cùng tính năng ép xung tiên tiến như AI Overclocking, AI Cooling II,... tích hợp bên trong chắc chắn là giải pháp năng lượng mạnh mẽ, tối ưu nhiệt lượng và kết nối thông minh.</p><br>

                        <b style="color:black">RAM Corsair DOMINATOR TITANIUM Black Heatspreader DDR5 96GB CMP96GX5M2B6400C32</b><br />
                        <p>
                            <b style="color:lightcoral">RAM Corsair DOMINATOR TITANIUM Black Heatspreader DDR5 96GB CMP96GX5M2B6400C32</b> Những chi tiết từ logo ASUS ROG đến
                            với 2 thanh ram dung lượng cực lớn 48GB (tổng là 96GB) chuẩn DDR5 mới nhất cùng với bus ram đến 6600Mhz cho tốc độ xử lý dữ liệu cực cao.
                        </p><br />

                        <b style="color:black">Ổ cứng SSD Samsung 990 PRO 2TB M.2 NVMe PCIe Gen 4.0 x4</b><br />
                        <p><b style="color:lightcoral"> Ổ cứng SSD Samsung 990 PRO 2TB M.2 NVMe PCIe Gen 4.0 x4 </b> là sản phẩm cực kỳ mới sử dụng công nghệ cao. Giao diện PCIe Gen 4.0 mang đến sự vượt trội hơn Gen 3 rất nhiều. Tốc độ của nó có thể lên tới 7450MB/s, đọc – ghi ngẫu nhiên đạt tới 1550K IOPS. Đây là một hiệu suất cực kỳ cao cho máy tính hoạt động với những tác vụ đòi hỏi yêu cầu cao. </p><br>

                        <b style="color:black">Nguồn Asus ROG STRIX 1000G-AURA Gaming Edition (Pci 5.0 - Full modular)</b><br />
                        <p> Tương thích chuẩn ATX 3.0 hiện đại, tùy biến nâng cao với LED RGB địa chỉ cùng với màn hình nguồn OLED giám sát điện năng tiêu thụ trong thời gian thực. Công nghệ 0dB giảm nhiễu đầu ra khi tải PSU từ 50% trở xuống. </p><br>

                        <b style="color:black">VGA ROG Strix GeForce RTX 4090 OC Edition 24GB GDDR6X</b><br />
                        <p> Card đồ họa VGA ROG Strix GeForce RTX 4090 OC Edition 24GB GDDR6X được trang bị vô số nâng cấp đáng kể về cả hiệu năng lẫn thiết kế. Cụ thể, bộ đa xử lý phát trực tuyến NVIDIA Ada Lovelace đem tới hiệu suất năng lượng cao gấp 2 lần, cùng với lõi Tensor thế hệ thứ 4 tăng gấp 2 lần hiệu suất AI. Ép xung (OC) mạnh mẽ, tăng xung nhịp 2640 MHz/ 2610 MHz. </p><br>

                        <b style="color:black">Vỏ Case Lian Li O11D Evo RGB Black</b><br />
                        <p><b style="color:lightcoral"> Vỏ case Lian Li O11D EVO RGB Black </b> Thiết kế cường lực trong suốt 2 mặt trước và mặt hông, đảm bảo độ bền và quan sát được rõ ràng hệ thống máy bên trong. Với không gian lưu trữ tối đa lên đến 9 ổ cứng SSD hoặc với 6HDD và 3SDD, giúp bạn dễ dàng lựa chọn hoặc nâng cấp ổ cứng nếu cần thiết. Hỗ trợ lắp đặt quạt ở cả 4 mặt case (trên, dưới, hông, sau) và 1 quạt ngay trên ổ cứng. Cuối cùng là hệ thống cổng I/O đầy đủ và vô cùng tiện lợi.</p><br>

                        <b style="color:black">Tông Kết</b><br />
                                                           <p>
                                                               Với sự mạnh mẽ về hiệu năng cũng như sự tinh tế về thiết kế của từng linh kiện, PC Gaming - Sentinel I4090 - BL xứng đáng là bộ PC Gaming quốc dân được săn đón nhiều nhất trong thời gian tới đây.
                                                               Hi vọng qua bài viết này, giúp anh em có thể lựa chọn cho mình bộ PC ưng ý nhất ! Ngoài ra, còn xây dựng cấu hình PC phù hợp với nhu cầu sử dụng của khách hàng.
                                                           </p><br>

', '
<p class="mb-4">
                    <b>CPU:</b> Intel Core i9 14900K 24C/ 32T (Up to 6.0 GHz, 36MB Cache, Raptor Lake Refresh) <br />
                    <b>Bo Mạch Chủ:</b> ASUS ROG STRIX Z790-F GAMING WIFI II<br />
                    <b>RAM:</b> Corsair DOMINATOR TITANIUM Black Heatspreader DDR5 96GB (48x2) 6400MT/s<br />
                    <b>Ổ cứng SSD:</b> Samsung 990 PRO 2TB M.2 NVMe PCIe Gen 4.0 x4<br />
