INSERT INTO `SanPham` (`ProductID`, `TenSanPham`, `Gia`, `HinhAnh`, `MoTa`, `ThongSoKyThuat`, `SoLuongTon`, `BrandID`, `CategoryID`) VALUES (3065, 'Bàn Phím Cơ Asus M704 Rog Azoth X (Wireless/ OLED LCD/ NXSMV2/ Storm/ US/ PBT/ Trắng)', 6790000, 'Banphim/banphim_new_23122025125529273/250-12857-ban-phim-co-asus-m704-rog-azoth-x-storm-v2-switch-1_new_23122025125529273.jpg', '<h2 style="margin: 18pt 0px 6pt; padding: 0px; box-sizing: border-box; font-family: &quot;Chakra Petch&quot;; background-color: rgb(255, 255, 255); line-height: 1.38;"><span style="margin: 0px; padding: 0px; box-sizing: border-box; font-family: inherit !important; font-size: 14pt;"><strong style="margin: 0px; padding: 0px; box-sizing: border-box; font-family: inherit !important;"><span style="margin: 0px; padding: 0px; box-sizing: border-box; font-family: Arial, sans-serif; background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; vertical-align: baseline; white-space-collapse: preserve;">Đánh Giá Chi Tiết </span></strong><a href="https://www.tncstore.vn/ban-phim-co-asus-m704-rog-azoth-x-storm-v2-switch.html" target="_blank" style="margin: 0px; padding: 0px; box-sizing: border-box; text-decoration-line: none; color: rgb(41, 50, 78); font-family: inherit !important;"><strong style="margin: 0px; padding: 0px; box-sizing: border-box; font-family: inherit !important;"><span style="margin: 0px; padding: 0px; box-sizing: border-box; font-family: Arial, sans-serif; color: rgb(255, 153, 0); background-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; font-variant-emoji: normal; vertical-align: baseline; white-space-collapse: preserve;">Bàn Phím Cơ Asus M704 Rog Azoth X (Wireless/ OLED LCD/ NXSMV2/ Storm/ US/ PBT/ Trắng)</span></strong></a></span></h2><p style="margin: 0pt 0px; padding: